import openpyxl, subprocess, os, itertools
base='/app/submission/allocation.xlsx'
def run(name, mutate, profile):
    wb=openpyxl.load_workbook(base); mutate(wb); p=f'/tmp/stage/pt/{name}.xlsx'; wb.save(p)
    od=f'/tmp/stage/pt/out_{profile}'; os.makedirs(od,exist_ok=True)
    subprocess.run(['soffice','--headless','--norestore',f'-env:UserInstallation=file:///tmp/{profile}','--convert-to','xlsx:Calc MS Excel 2007 XML','--outdir',od,p],capture_output=True)
    r=openpyxl.load_workbook(f'{od}/{name}.xlsx',data_only=True)['Summary']
    return [[r.cell(i,j).value for j in (2,3,4)] for i in (2,3,4)], r['D6'].value
def expect(wb_mut):
    pass
def reorder(wb):
    ws=wb['Rates']; rows=[[ws.cell(i,j).value for j in (1,2,3)] for i in (2,3,4)]
    rows=[rows[2],rows[0],rows[1]]
    rows[0][2]=7; rows[1][2]=1.5; rows[2][2]=4   # 02->7, 010->1.5, 002->4
    for i,r in enumerate(rows,2):
        for j,v in enumerate(r,1): ws.cell(i,j).value=v
def append(wb):
    ws=wb['Costs']; ws['A1000']='BILL-999'; ws['B1000']=ws['B6'].value; ws['C1000']=500.25
    ws['A7']='BILL-006'; ws['C7']=123; ws.row_dimensions[7].hidden=True
def both(wb): reorder(wb); append(wb)
for prof in ('lo_profile','lo_default'):
    for n,m in [('reorder',reorder),('append',append),('both',both)]:
        print(prof,n,run(n,m,prof))
